pub struct DirView { m: Arc<Membrane>, raw: Rc<dyn Dir> }

impl Dir for DirView {
    fn open(&self, path: &str) -> Result<File, Error> {
        if self.m.revoked() {
            return Err(Error::Revoked);          // check and forward together
        }
        let f = self.raw.open(path)?;
        Ok(self.m.wrap_file(f))                  // wrap the way out
    }
}
